corrected_code:
const express = require('express');
const Stripe = require('stripe');
const db = require('../db');

const app = express();
app.use(express.json());
const stripe = new Stripe(process.env.STRIPE_KEY);

app.post('/api/connect/transfers/reverse', async (req, res) => {
  const { transferId, amount, stripeAccountId } = req.body;

  // Verify that the transfer and connected account belong to the authenticated merchant
  const transferRecord = await db('merchant_transfers')
    .where({
      transfer_id: transferId,
      stripe_account_id: stripeAccountId,
      merchant_id: req.user.merchantId
    })
    .first();
  if (!transferRecord) {
    return res.status(403).json({ error: 'Access denied: transfer does not belong to your account' });
  }

  try {
    const reversal = await stripe.transfers.createReversal(
      transferId,
      { amount: Math.round(amount * 100) },
      { stripeAccount: stripeAccountId }
    );

    return res.json({ status: 'Transfer reversed', reversalId: reversal.id });
  } catch (err) {
    return res.status(500).json({ error: 'Transfer reversal failed' });
  }
});

module.exports = app;
